from collections import defaultdict

def find_minimum_time(n, m, volcanoes):
    graph = defaultdict(list)
    for x, y in volcanoes:
        graph[x].append(y)
        graph[y].append(x)

    visited = [[0 for _ in range(n)] for _ in range(n)]
    depth = 0

    def dfs(x, y):
        if visited[x][y] > depth:
            return
        visited[x][y] = depth
        if x == n - 1 and y == n - 1:
            return True
        for neighbor in graph[min(x, y), max(x, y)]:
            if dfs(max(x, y), min(x, y)):
                return True
        return False

    for i in range(1, n + 1):
        depth += 1
        if not dfs(1, i):
            return -1
    return depth

