        return 1
    else:
        return gcd(n, find_gcds(math.gcd(n, n - 1)))


def triangles(y):
    """Generate all triangles with top points at (x, y) and endpoints x and y."""
    for x in range(1, y):
        yield (x, y), (x, x), (y, x)


@lru_cache(maxsize=None)
def count_links(n, current, n_links):
    if current == n:
        return 1
    else:
        return sum(count_links(n, new_link[0], n_links + abs(current - new_link[1])) for new_link in triangles(current))

def solve(MAX):
    main = count_links(MAX, 0, 0)
    sols = pow(MAX * 5, 3, MAX)
    sols = (sols - sols//main)*(MAX - main)//MAX // (MAX // sols)
    mod = 10**9 + 7
    return sols % mod


