                match = bisect.bisect_left(self.histogram, x)
                while match < len(seq) and seq[match] == x:
                    x -= 1
                    if x > 0:
                        break
                else:
                    yield x+1
                    seq[match] -= 1
                    break
                seq[match] -= 1
                if seq[match] == 0:
                    seq.pop(match)
                    match -= 1
                else:
                    x %= len(seq)
                    prev[x] = True


    def parse_snakes(self):
        gaps = defaultdict(list)
        for pos, t in enumerate(self.expansions):
            for x in map(gaps.get, t):
                x.sort()
                if not x:
                    continue
                elif x[-1] == pos:
                    if x[-1] - 1 > gap_max:
                        gap_max = x[-1] - 1
                        q = [x[-1] - 1]
                    else:
                        q = [x[-1] - 1, x[-1]]
                else:
                    if x[-1] == pos:
                        g = x.index(pos)
                    else:
                        g = len(x) - (len(x) - pos)
                    if g == len(x):
                        g = 1
                        q = x
                    gaps[pos].append(q)
        self.gaps = gaps

    def normalize(self):
        self.hist = [0] * 10
        self.full = defaultdict(int)
        for x in self.histogram:
            self.hist[x] -= 1
            if self.hist[x] > self.full[x]:
                del self.histogram[x]
                self.histogram[x] = 0

        self.histogram = sorted(self.histogram, reverse=True)
        self.histogram.insert(0, 0)

    def recalc(self):
        prev = set(self.histogram[i] > 0 for i in range(-1,-10,-1))
        self.normalize()
        return {x: i for i, x in enumerate(self.histogram)}

    def __call__(self, update):
        res = []
        if update.type == 1:
            self.update_hist(update.p, update.h)
        else:
            self.prune_gaps()
            self.update_dic()
            for x in self.snakes.get(update.x, []):
                res.append(self.recalc(his)[x])
        return " ".join(map(str, res))

