        self.orientation = self._determine_orientation()
        self.available_moves = self._get_possible_moves()
        self.winner = None

    def _determine_orientation(self):
        for i in range(len(self.state)):
            if self.state[i] != '.' and self.state[i] in ('A', 'B'):
                return self.state[i]  # Determine if the player is 'A' or 'B'
        return '.'  # If no character is present, it's empty

    def _get_possible_moves(self):
        if '.' in self.state:  # Check if there's an empty cell
            for row in range(len(self.state)):
                if row == 0 and self.state[row] in ('A', 'B'):
                    # Player A's first move on the leftmost position
                    directions = []
                    for col in range(row, len(self.state)):
                        if self.state[col] == '.':
                            directions.append(col)
                    return directions
                if row == len(self.state) - 1 and self.state[row] in ('A', 'B'):
                    # Player B's first move on the rightmost position
                    directions = []
                    for col in range(row + 1, len(self.state)):
                        if self.state[col] == '.':
                            directions.append(col)
                    return directions
        return []

    def make_move(self, col):
        if col < 0 or col >= len(self.state):  # Check index bounds
            return
        if self.orientation == 'A' and col < len(self.state) - 1:
            if self.state[col + 1] == '.':
                self.state = self.state[:col + 1] + 'A' + self.state[col + 2:]
        else:
            if self.state[col - 1] == '.':
                self.state = self.state[:col] + 'B' + self.state[col + 1:]

    def alternate_moves(self):
        choices = set(range(len(self.state)))  # Set of all possible valid positions
        if 'A' not in self.state:  # Player A has no valid moves, so player B wins
            return None
        else:
            for col in choices:
                if self.state[col] == '?':  # Check for empty positions
                    move = self.make_move
                    break
            else:
                return None  # No more choices if no moves are possible

