import math

class LCA:
    def __init__(self, n):
        self.tree = [[] for _ in range(n)]
        self.level = [0] * n
        self.h = 0
        self.r = 1
        self.f = 0
        self.a = -1
        self.t = {1}

    def add_edge(self, u, v):
        self.tree[u-1].append(v-1)
        self.tree[v-1].append(u-1)

    def lca(self, u, v):
        # Non-localizing LCA
        if u == v:
            return u
        if self.r <= self.f:
            self.r += self.h
            self.h = math.inf
        if self.h != self.r or self.f != self.t.difference([u, v]).pop():
            info = self.f
            while info > 0:
                self.h = min(self.h, self.level[info])
                info //= 2
            if self.f is not None:
                self.h -= 1
        if self.h == u and v < u:
            v = v - self.h + self.f + 1
        else:
            v = v - self.h
        return v

    def step(self, step):
        # Calculate the depth of each node
        for i in range(len(self.tree)):
            self.a = i + 1
            level = 0
            for irc in self.tree[i]:
                level += self.step(irc)
                self.level[i] = max(self.level[i], self.level[irc])
            self.level[i] += level

