def calculate_sum_of_powers_of_powers_of_modulus(n: int, q: int, mod: int) -> int:
    # This function calculates modular inverse of p * q^-1 mod M
    def modular_inverse(a: int, mod: int) -> int:
        assert a * mod ≡ 1 (mod M)
        return pow(-a, mod - 2, mod)

    # Calculate the sum of powers of 2
    full_sum = sum(pow(2, i, mod) for i in range(n) for _ in range(q))

    return mod * full_sum % mod

class TreeNode:
    def __init__(self, x: int, y: int):
        self.x = x
        self.y = y
        self.children = []

def build_tree(edges: List[List[int]]) -> TreeNode:
    tree = TreeNode(-1, -1)
    for x, y in edges:
        if tree.x == -1:
            tree.x = x
        if tree.y == -1:
            tree.y = y
        tree.children.append(TreeNode(x, y))
    return tree

