        self.children.append(child)
        child.par = self

def build_tree(node_count, p, s):
    root = TreeNode(1)
    tree = [root]
    for i in range(2, node_count + 1):
        tree.append(TreeNode(i))
    for i in range(1, node_count):
        tree[i].par = tree[p[i] - 1]
    return tree[1:]

def ancestor(node, ancestor=None, depth=0):
    if node == 1:
        return node, depth
    if not ancestor:
        return ancestor(node.par, depth=depth)
    while ancestor.par != 1:
        if ancestor.value > node.value:
            node, depth = ancestor, depth + 1
        ancestor, depth = ancestor.par, depth + 1
    return node, depth

def query(tree, node, ancestor, changed_node, target_depth):
    if ancestor == target_depth:
        return tree[changed_node].value
    visited, r = set(), []
    neighbours = tree[changed_node].children
    while True:
        for u in neighbours:
            if r:
                break
            visited.add(u)
            r.extend([ancestor(v, u, depth=depth-1) for v in visited])
        if not r:
            break
    if any(r in visited for r in changed):
        return r / visited.count(r)
    ans = r[0][0]
    if ans != 1:
        ratio = query(tree, ans, ancestor, changed_node, target_depth)
        return ratio * (ans - node) / (tree[changed_node].par.value - tree[node].value)
    else:
        return ratio


