import sys

def find_min_distance(n, m, volcanoes):
    # Initialize the distance array considering only (1,1)
    distance = [(0, 1)] + [(sys.maxsize, 0)] * (n**2 - 1)
    # Initialize the directions and the current position
    dx, dy = -1, 1
    position = 0

    # For each row that doesn't have an obstacle
    for _ in range(n):
        # Table for left neighbors: 0 (down, n-1) 1 (up, n) 2 (right, 1) 3 (right, n-1)
        left_neighbors = [0] * 4 + [1, 2, 3]
        for j in range(1, n):
            pos = distance[position][1]
            # Keep moving down until after the row with the volcano
            while distance[pos][1] >= m:
                pos += 1
            # Get the last column of the left neighboring rows
            down_neighbors = sorted(distance[pos] + [col - pos for col in range(n)], reverse=True)[:m]
            # If we're interested only in smallest distance
            if len(down_neighbors) > 0:
                for i in range(len(left_neighbors)):
                    x, y = left_neighbors[i], j
                    # Move in the direction of smallest neighbors when similar ones also have a connection
                    if i < 3:
                        dx, dy = dx * down_neighbors[x][1], dy * down_neighbors[x][1]
                    elif dx * down_neighbors[x][1] > dy * down_neighbors[x][1]:
                        dx, dy = -1, 1
            # Not the current row position, select from the current row neighbors
            for x, y in range(1, m):
                step = downward_distance(distance[pos[n-1]][1] - y, n-1) 
                # Keep moving up until before the volcano
                steps = step * dy
                neighbor = (n ** 2 - 1) + steps
                # Check that neighbor hasn't been thought yet
                if neighbor >= n ** 2 - m:
                    return -1
                if distance[neighbor][0] > neighbor ** 2 + step:
                    for k in range(4):
                        if min(dx, dy)[k] != 0:
                            if dx == 0 or dy == 0:
                                parallel = k < 2
                            elif dx > 0:
                                parallel = k < 1
                            else:
                                parallel = k > 2
                            neighbor += parallel * x * min(dx, dy)[k]
                            neighbor *= adjacent_left(neighbor, left_neighbors, 2)
                            distance[neighbor] = neighbor ** 2 + step
                elif steps > distance[neighbor][1]:
                    distance[neighbor] = steps
        position = (n ** 2 - 1) if distance[distance[-1][1]][0] else position

    return distance[-1][0] 

def adjacent_left(i, left_neighbors, _right):
    if len(left_neighbors) == 1:
        return left_neighbors[0]

    nxt_pos = sorted([nxt[i] for nxt in [left_neighbors[_right], adjacent_right(i)]] + [i])
    while nxt_pos[0] > 0 and len(set(nxt_pos)) > 2 and (
        nxt_pos[0] - 1 not in left_neighbors[_right] and 
        nxt_pos[0] - 1 not in _right
    ):
        nxt_pos.pop(0)

    return nxt_pos[0]

def adjacent_right(i):
    nxt_pos = sorted([nxt[i] for nxt in [left_neighbors, adjacent_left(i)]])
    while nxt_pos[0] > 0 and len(set(nxt_pos)) > 2 and (
        nxt_pos[0] - 1 not in left_neighbors[0] and 
        nxt_pos[0] - 1 not in nxt_pos[1]
    ):
        nxt_pos.pop(0)
    return nxt_pos and nxt_pos[0]

def downward_distance(step, length):
    return -step / (length - 1) * step * ((length * length - step * step) / 2.0) + step * step / 2.0

