    while True:
        yield (low[0] + 1, x), (high[1] - 1, y)
        if low[0] == high[0]:
            if (low[0] + 1, low[1]) not in visited:
                yield (low[0] + 1, low[1]), high[::-1]
            break
        if (low[1] == low[0]):
            if (x, low[1]) not in visited:
                yield (low[0], low[1]), high[::-1]
