from heapq import heappop, heappush

MOD = 10**9 + 7

def build_tree(n, edges):
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)
    return tree

def dijkstra(tree, start):
    n = len(tree)
    distance = [float('inf')] * n
    distance[start] = 0
    q = [(0, start)]

    while q:
        dist, u = heappop(q)
        for v in tree[u]:
            if distance[v] > distance[u] + 1:
                distance[v] = distance[u] + 1
                heappush(q, (distance[v], v))

    return distance

def bfs_tree(tree, start, d):
    n = len(tree)
    que = [[0, start]]
    visited = [False] * n

    while que:
        d, u = heappop(que)

        for v in tree[u]:
            if not visited[v]:
                visited[v] = True
                que.append([d+1, v])

    visited[start] = True
    return visited, que[-1][0]

