            expected_values[u] += d
            expected_values[u] %= MOD
    for u in range(len(tree)):
        if u != v:
            if visited[u]:
                expected_values[u] += 1
                expected_values[u] %= MOD
    new_d = sum(expected_values) // (len(tree) - 1)
    return new_d

def query_type_2(v):
