        if (i+1) % n == 0:
            df += 1
        elif i // n + 1 == n:
            dc += 1

    for x, y in volcanoes:
        matrix[x-1][0] -= 1
        matrix[y-1][1] -= 1

    min_heap = [(0, 0)]
    visited = {}

    while min_heap:
        weight, curRow = heappop(min_heap)
        if (curRow, weight) in visited:
            continue
        visited[(curRow, weight)] = True
        if curRow >= n - 1:
            return weight
        for i in [curRow - 1 if curRow != 0 else None, curRow + 1]:
            for j in [weight, weight + 1]:
                if i is not None and matrix[i][0] < j and (i, j) not in volcanoes:
                    heappush(min_heap, (i + n * n, j + n * n))
                if j < n**2 and (i, j) not in volcanoes:
                    heappush(min_heap, (i, j))
    return -1

# Example usage
n, m = map(int, input().split())
volcanoes = [tuple(map(int, input().split())) for _ in range(m)]
print(min_time_to_land(n, m, volcanoes))
