from collections import deque

def is_win(s):
    n = len(s)
    queue = deque()

    # Initialize the queue with the last character in the player's chosen direction
    if s[-1] == 'A':
        queue.append('B')
    else:
        queue.append('A')

    # Iterate through the string from the end to the beginning
    for char in s[::-1]:        
        if char in 'AB':
            if (queue[0] == 'A' and queue[-1] == 'B') or (queue[0] == 'B' and queue[-1] == 'A'):
                queue.popleft()
            else:
                return 'B'
        else:
            if queue:
                queue.popleft()

    return 'A'

