from collections import Counter
from typing import List, Tuple

def bipartite_coloring(nA, nB, edges: List[Tuple[int, int]]) -> str:
    m = len(edges)
    colors = [0] * (m + 1)
    available = set(range(1, m + 1))

    result = []

    def dfs(v):
        color = colors[v]
        if color != 0:
            return True
        visited[v] = True
        for u in range(m):
            if color != 0 and edges[u][1] == v:
                if not dfs(u):
                    return False
        visited[v] = False
        colors[v] = color
        for u in range(m):
            if edges[u][0] == v:
                result.append(colors[u])
                available.remove(u + 1)
        return True

    visited = [False] * (m + 1)
    for v in range(1, m + 1):
        if not visited[v]:
            if not dfs(v):
                return "" # No valid coloring
    available = set(range(1, m + 1))

    k = len(available)
    result = []
    while available:
        current = next(iter(available))
        result.append(result[current - 1]) # Remove the bubble
        result.pop()
        available.remove(current)

    colors = [0] * m
    for color in range(1, k + 1):
        for v in range(1, m + 1):
            if v in result:
                colors[v - 1] = color
                result.remove(v)
                available.update(range(1, v))
                available.update(range(v + 1, v + m + 1))
                break

    result = ' '.join(map(str, colors))
    return f'{k}\n' + result + '\n'
